        "./result/img/" + new Date().getTime() + ".png",
        bufferData,
        function (err) {
          if (err) {
          } else {
            console.log("图片保存成功");
          }
        }
      );
    }
  });

  function drawPolygon(points, scalex, scaley, color) {
    // console.log(scalex, scaley);
    ctx.beginPath();
    for (let i = 0; i < points.length; i++) {
      let point = points[i];
      //   console.log(point);
      let x = Number(point["lot"]);
      let y = Number(point["lat"]);
      //   console.log(x, y);
      let l = (x - xmin) / scalex;
      let t = height - (y - ymin) / scaley;
      //   console.log(l, t);
      if (i === 0) {
        ctx.moveTo(l, t);
      } else {
        ctx.lineTo(l, t);
      }
    }
    // ctx.globalCompositeOperation = "destination-over";
    ctx.fillStyle = color;
    ctx.strokeStyle = "#fff";
    ctx.closePath();
    ctx.stroke();
    ctx.fill();
  }
}

