## 1、将中国标准时间转为 yyyymmdd

```javascript
export function getYYYYMMDD(string) {
  const d = new Date(string);
  const datetime =
    d.getFullYear() +
    "-" +
    (d.getMonth() + 1) +
    "-" +
    d.getDate() +
    " " +
    d.getHours() +
    ":" +
    d.getMinutes() +
    ":" +
    d.getSeconds();

