			let radio = (((oldSize - newSize) / oldSize) * 100).toFixed(2);
			that.fileList.map((item) => {
				item.uid == uid ? (item.downLink = `${url}/${name}`) : "";
				item.uid == uid ? (item.radio = `${radio}`) : "";
			});
			that.$forceUpdate();
			console.log(this.fileList);
		}
	})
	.catch((err) => {
		console.log(err);
		that.$message.error(err);
	});
