> 引入 babel-plugin-transform-remove-console 插件
> vue 项目内创建 babel.config.js 文件

```javascript
// babel.config.js
const prodPlugins = [];
if (process.env.NODE_ENV === "production") {
  prodPlugins.push("transform-remove-console");
}

module.exports = {
  presets: ["@vue/cli-plugin-babel/preset"],
  plugins: [...prodPlugins],
};
```

