        to: that.data.userInfo.emId,
        chatType: "singleChat",
        ext: {
          userExt: JSON.stringify(a),
        },
        success: function () {},
      };
      msg.set(set_options);
      WebIM.conn.send(msg.body);
      msg.body.ext.userExt = JSON.parse(msg.body.ext.userExt);
      that.updateMessage(msg.body);
      that.setData({
